'use strict';

// V27 : charge physique fictive, distincte de la condition instantanée.
// Modèle : 0..100 ; la récupération ne modifie que la condition, déjà utilisée par skill/fitScore.
const PHYSICAL_PLANS={collective:'Suivre le collectif',repos:'Récupération',normal:'Normale',intense:'Intensive'};
function physicalState(p){return p.physicalLoad&&p.physicalLoad.version===1?p.physicalLoad:{version:1,fatigue:0,plan:'collective'}}
function ensurePhysicalLoad(p){if(!p.physicalLoad)p.physicalLoad={version:1,fatigue:0,plan:'collective'};return p.physicalLoad}
function physicalLoadValue(p){return physicalState(p).fatigue}
function physicalPlan(p){return physicalState(p).plan}
function physicalModeFor(p,ci){if(p.injury)return 'repos';if(ci!==S.club)return physicalLoadValue(p)>=55||p.condition<60?'repos':'normal';const selected=physicalPlan(p);return selected==='collective'?S.training:selected}
function physicalTrainingOutcome(p,mode){const injured=!!p.injury,selected=injured?'repos':mode,current=physicalLoadValue(p);const fatigue=clamp(current+(selected==='repos'?-20:selected==='normal'?-10:6),0,100);const base=injured?15:selected==='repos'?30:selected==='normal'?20:8;const reduction=Math.min(10,Math.floor(fatigue/10));return {fatigue,condition:clamp(p.condition+Math.max(0,base-reduction),injured?0:20,100)}}
function applyPhysicalTraining(p,mode){const next=physicalTrainingOutcome(p,mode),state=ensurePhysicalLoad(p);state.fatigue=next.fatigue;p.condition=next.condition;return next}
function setPhysicalTraining(id,plan){if(!S||S.live||S.trained||S.phase==='ended'||!Object.prototype.hasOwnProperty.call(PHYSICAL_PLANS,plan))return false;const p=player(id);if(!p)return false;ensurePhysicalLoad(p).plan=plan;save();render();return true}
function physicalLoadPreviewText(p){if(S.trained)return 'Séance déjà appliquée';const next=physicalTrainingOutcome(p,physicalModeFor(p,S.club));return 'Après séance : '+next.condition+' % de condition · charge '+next.fatigue+'/100'}
function physicalStaffAdvice(){const high=starters().filter(p=>physicalLoadValue(p)>=45).sort((a,b)=>physicalLoadValue(b)-physicalLoadValue(a));if(high.length)return high.slice(0,2).map(p=>p.name+' ('+physicalLoadValue(p)+'/100)').join(', ')+' : charge cumulée élevée. Envisagez récupération ou rotation avant le prochain match.';return mean(starters().map(p=>p.condition))<70?'Votre XV est fatigué. Privilégiez la récupération et donnez du temps de jeu aux remplaçants.':'Le groupe est prêt à travailler. Ajustez individuellement la charge des titulaires dans Effectif & 23.'}
function physicalTrainingPreview(){const selected=starters().filter(p=>physicalLoadValue(p)>=35).sort((a,b)=>physicalLoadValue(b)-physicalLoadValue(a)).slice(0,3);return '<p class="help">Définissez un mode collectif ici, puis des exceptions par joueur dans Effectif & 23. Projection avant match, hors minutes futures.</p>'+(selected.length?'<div class="physical-rotation-preview"><strong>À surveiller :</strong> '+selected.map(p=>p.name+' ('+physicalLoadValue(p)+'/100, '+physicalLoadPreviewText(p)+')').join(' · ')+'</div>':'')}
function recordPhysicalMatchLoad(l){if(l.physicalLoadVersion!==1||l.physicalLoadRecorded)return false;l.physicalLoadRecorded=true;for(let side=0;side<2;side++){const sheet=l.sheets[side];for(const id of sheet.used){const p=matchPlayer(l,side,id),minutes=Math.min(80,Math.max(0,sheet.minutes[id]||0));if(!p||!minutes)continue;const state=ensurePhysicalLoad(p);state.fatigue=clamp(state.fatigue+Math.round(minutes*18/80),0,100)}}return true}

// Fictional career curves: ceilings apply to the underlying rating, not the displayed role note.
function ensureDevelopment(p){if(p.dev)return p;const h=seedHash(p.id),young=p.age<=22,mid=p.age<=26;let margin=young?8+h%14:mid?4+h%9:p.age<=29?1+h%5:h%3;if(p.id.startsWith('academy-'))margin=10+h%9;p.dev={potential:clamp(p.rating+margin,p.rating,99),xp:0,seasonStart:p.rating,minutes:0,appearances:0,careerMinutes:0,history:[],retireAge:Math.max(p.age+1,(p.fam<=3?35:34)+h%5),lastYear:0,decline:0};return p}
function potentialAtRole(p){ensureDevelopment(p);return roleNote({...p,rating:p.dev.potential})}
function ageGrowth(p){return p.age<=22?1.4:p.age<=26?1:p.age<=29?.5:p.age<=31?.15:0}
function growPlayer(p,xp){ensureDevelopment(p);if(!Number.isFinite(xp)||xp<=0||p.rating>=p.dev.potential){p.dev.xp=p.rating>=p.dev.potential?0:p.dev.xp;return 0}const before=p.rating;p.dev.xp+=xp;while(p.dev.xp>=1&&p.rating<p.dev.potential){p.rating++;p.dev.xp-=1}if(p.rating>=p.dev.potential)p.dev.xp=0;return p.rating-before}
function developmentTraining(p,mode){ensureDevelopment(p);if(p.injury||mode==='repos')return;const amount=mode==='intense'?.10:.055;growPlayer(p,amount*ageGrowth(p)*(p.condition<50?.5:1))}
function recordDevelopmentMatch(l){if(l.developmentRecorded)return;l.developmentRecorded=true;for(let side=0;side<2;side++){const s=l.sheets[side];for(let id of s.used){const p=matchPlayer(l,side,id);if(!p)continue;ensureDevelopment(p);const minutes=Math.max(0,(s.minutes[id]||0)-(l.devBaseline?.[side]?.[id]||0));if(!minutes)continue;p.dev.minutes+=minutes;p.dev.careerMinutes+=minutes;p.dev.appearances++;growPlayer(p,minutes/80*.12*ageGrowth(p)*Math.max(.5,p.condition/100))}}}
function academyPlayer(ci,slot,season,index,emergency=false){const id=`youth-${ci}-${season}-${index}`,h=seedHash(id);let p={id,name:FIRST[h%FIRST.length]+' '+LAST[Math.floor(h/31)%LAST.length],pos:POS[slot],fam:FAMILIES[slot],age:17+h%3,rating:emergency?55+h%8:52+h%15,condition:100,injury:0,salary:2000};ensureSkills(p);ensureDevelopment(p);p.dev.potential=Math.max(p.rating,emergency?68+h%10:76+h%19);p.academy=true;return p}
function intakeYouth(){const d=S.development;if(d.intakeSeason===S.season)return;d.intakeSeason=S.season;for(let i=0;i<4;i++){let slot=(S.season*3+i*4)%15;d.academy.push(academyPlayer(S.club,slot,S.season,i))}d.academy=d.academy.slice(-12);news(`Quatre nouveaux espoirs rejoignent le centre de formation. Consultez leur potentiel avant de les intégrer au groupe professionnel.`)}
function setupDevelopment(backup=false){if(!S)return;const fresh=!S.development;if(fresh&&backup){try{if(!gameStorage.getItem('bdt-backup-development'))gameStorage.setItem('bdt-backup-development',JSON.stringify(S))}catch(e){}}
S.development=S.development||{version:1,academy:[],intakeSeason:0,rolledSeason:0,retired:[]};S.clubs.forEach(c=>c.players.forEach(ensureDevelopment));S.market.forEach(ensureDevelopment);S.economy.freeAgents.forEach(ensureDevelopment);if(fresh&&S.live)S.live.devBaseline=S.live.sheets.map(s=>({...s.minutes}));intakeYouth();if(fresh&&backup)news('Formation et carrières activées : niveaux, contrats et résultats conservés. Le suivi des minutes commence maintenant.')}
function promoteYouth(id){if(economyLocked())return false;const d=S.development,p=d.academy.find(p=>p.id===id);if(!p||club().players.length>=42){toast('Promotion impossible : joueur indisponible ou effectif complet (42 joueurs).');return false}d.academy=d.academy.filter(p=>p.id!==id);p.academy=false;p.joinedSeason=S.season;p.joinedRound=S.round;p.contractEnd=contractBase()+1;club().players.push(p);transferEvent(`${p.name} signe son premier contrat professionnel jusqu’à la fin de la saison ${p.contractEnd}, à ${money(p.salary)} par semaine.`);save();render();toast('Le jeune est disponible dans votre effectif.');return true}
function retirementSeason(p){ensureDevelopment(p);return S.season+Math.max(0,p.dev.retireAge-p.age-1)}
function ageDevelopmentPlayer(p){ensureDevelopment(p);if(p.dev.lastYear===S.season)return;p.dev.lastYear=S.season;const d=p.dev;d.history.push({season:S.season,age:p.age,start:d.seasonStart,end:p.rating,minutes:d.minutes,appearances:d.appearances});d.history=d.history.slice(-12);p.age++;const threshold=p.fam<=3?34:32;const decline=p.age>=threshold?(p.age>=37?2:1):0;p.rating=clamp(p.rating-decline,45,99);d.potential=Math.max(p.rating,d.potential-decline);if(decline){p.skills.speed=clamp(p.skills.speed-decline,15,99);p.skills.stamina=clamp(p.skills.stamina-decline,15,99);p.skills.mental=clamp(p.skills.mental+decline,15,99)}d.decline=decline;d.seasonStart=p.rating;d.minutes=0;d.appearances=0;d.xp=0;p.condition=100;p.injury=0}
function rollDevelopmentYear(){const d=S.development;if(d.rolledSeason===S.season)return;d.rolledSeason=S.season;const retiredIds=new Set(),seen=new Set();const all=[...S.clubs.flatMap(c=>c.players),...S.economy.freeAgents,...d.academy];for(let p of all){if(seen.has(p.id))continue;seen.add(p.id);ageDevelopmentPlayer(p);if(p.age>=p.dev.retireAge){retiredIds.add(p.id);let owner=S.clubs.find(c=>c.players.some(x=>x.id===p.id));d.retired.unshift({name:p.name,id:p.id,age:p.age,season:S.season,club:owner?.name||p.formerClub||'Agent libre',minutes:p.dev.careerMinutes});if(owner?.id===S.club)transferEvent(`${p.name} prend sa retraite à ${p.age} ans. Son salaire ne sera plus versé.`)}}for(let c of S.clubs)c.players=c.players.filter(p=>!retiredIds.has(p.id));S.economy.freeAgents=S.economy.freeAgents.filter(p=>!retiredIds.has(p.id));S.market=S.market.filter(p=>!retiredIds.has(p.id));d.academy=d.academy.filter(p=>p.age<=21);S.lineup=S.lineup.map(id=>retiredIds.has(id)?null:id);S.reserves=S.reserves.map(id=>retiredIds.has(id)?null:id);d.retired=d.retired.slice(0,80)}
function renewAIYouth(){for(let c of S.clubs){if(c.id===S.club)continue;let sheet=buildSheet(c),serial=0;for(let i=0;i<23;i++){let isBench=i>=15,j=isBench?i-15:i,id=isBench?sheet.bench[j]:sheet.lineup[j];if(id)continue;const slot=isBench?[1,0,2,3,5,8,9,10][j]:j,p=academyPlayer(c.id,slot,S.season,100+serial++);p.rating=clamp(c.base-15+seedHash(p.id)%9,54,82);delete p.skills;ensureSkills(p);delete p.dev;ensureDevelopment(p);p.contractEnd=S.season+2;p.academy=false;c.players.push(p);sheet=buildSheet(c)}for(let i=0;i<2&&c.players.length<34;i++){let p=academyPlayer(c.id,(S.season+i*7+c.id)%15,S.season,i);p.contractEnd=S.season+2;p.academy=false;c.players.push(p)}}}
function beginDevelopmentSeason(){intakeYouth();renewAIYouth()}
function developmentBadge(p){ensureDevelopment(p);return p.dev.decline?'Phase de déclin':p.rating>=p.dev.potential?'Potentiel atteint':p.age<=22?'En développement':p.age<=29?'En progression':'Joueur expérimenté'}
function playerDevelopmentHTML(p){ensureDevelopment(p);const d=p.dev,change=p.rating-d.seasonStart;return `<div class="devsummary"><div><span class="eyebrow">POTENTIEL AU POSTE</span><b>${potentialAtRole(p)} <small>/ 100</small></b></div><div><span class="eyebrow">ÉVOLUTION CETTE SAISON</span><b>${change>0?'+':''}${change} <small>niveau général</small></b></div><div><span class="eyebrow">TEMPS DE JEU</span><b>${Math.round(d.minutes)} <small>min · ${d.appearances} matchs</small></b></div></div><p class="help">${developmentBadge(p)} · Retraite prévue à l’issue de la saison ${retirementSeason(p)} (${d.retireAge} ans au passage à l’intersaison). Le potentiel est un plafond de jeu, sans garantie de l’atteindre.</p>${d.history.length?`<details><summary>Historique des saisons</summary><div class="tablewrap"><table><thead><tr><th>SAISON</th><th>NIVEAU GÉNÉRAL</th><th>MINUTES</th><th>MATCHS</th></tr></thead><tbody>${d.history.slice().reverse().map(h=>`<tr><td>${h.season}</td><td>${h.start} → ${h.end}</td><td>${Math.round(h.minutes)}</td><td>${h.appearances}</td></tr>`).join('')}</tbody></table></div></details>`:''}`}
function inspectCareerPlayer(id){const p=club().players.find(p=>p.id===id)||S.market.find(p=>p.id===id)||S.development.academy.find(p=>p.id===id);if(!p)return;ensureSkills(p);modal=`<div class="modalback"><section class="modal playerdetail" role="dialog" aria-modal="true" aria-label="Fiche joueur"><div class="row" style="margin-top:0"><span class="tag">${p.pos} · ${p.age} ans</span><button class="small" onclick="closeModal()">Fermer ×</button></div><h2>${p.name}</h2><p>Note au poste : <strong>${roleNote(p)}</strong> · Condition : ${Math.round(p.condition)}%${p.injury?' · Blessé '+p.injury+' sem.':''}</p><p class="help">${p.academy?'Centre de formation · Aucun salaire professionnel':(Number.isInteger(p.contractEnd)?contractLabel(p):'Agent libre')+' · '+money(p.salary)+' / semaine'}</p>${playerDevelopmentHTML(p)}<div class="attributes">${Object.entries(ATTR).map(([k,label])=>`<div><div class="row"><span>${label}</span><strong>${Math.round(skill(p,k))}</strong></div>${meter(skill(p,k))}</div>`).join('')}</div><p class="help">La condition modifie l’efficacité en match. L’âge, l’entraînement et les minutes réellement disputées déterminent la progression.</p></section></div>`;render()}
function formationView(){let young=club().players.filter(p=>p.age<=23);return heading('CONSTRUIRE LA RELÈVE','Le centre de formation.','Quatre nouveaux espoirs à chaque saison. À vous de leur ouvrir les portes du groupe professionnel.')+`<div class="stats"><div class="card stat"><span class="eyebrow">ESPOIRS</span><b>${S.development.academy.length}</b><small>Hors masse salariale professionnelle</small></div><div class="card stat"><span class="eyebrow">JEUNES PROS ≤ 23 ANS</span><b>${young.length}</b><small>${Math.round(young.reduce((n,p)=>n+(p.dev?.minutes||0),0))} minutes cette saison</small></div><div class="card stat"><span class="eyebrow">RETRAITES À ANTICIPER</span><b>${club().players.filter(p=>retirementSeason(p)<=S.season+1).length}</b><small>Cette saison ou la prochaine</small></div><div class="card stat"><span class="eyebrow">PROGRESSION DU GROUPE</span><b>+${club().players.reduce((n,p)=>n+Math.max(0,p.rating-p.dev.seasonStart),0)}</b><small>Points de niveau général acquis</small></div></div><div class="notice" style="margin:0 0 22px">Les espoirs s’entraînent mais ne disputent pas de matchs de jeunes dans cette version. Ils restent au centre jusqu’à 21 ans inclus. Une promotion est gratuite, avec un salaire de 2 000 € par semaine et un contrat jusqu’à la fin de la saison ${contractBase()+1}.</div><div class="marketgrid">${S.development.academy.map(p=>`<div class="card marketplayer"><span class="tag">${p.pos} · ${p.age} ANS</span><h3>${p.name}</h3><div class="row"><span>Note au poste</span><strong>${roleNote(p)}</strong></div><div class="row"><span>Potentiel au poste</span><strong>${potentialAtRole(p)}</strong></div>${skillChips(p)}<div class="contractactions"><button class="small" onclick="inspectPlayer('${p.id}')">Fiche complète</button><button class="primary small" onclick="promoteYouth('${p.id}')" ${club().players.length>=42?'disabled':''}>Promouvoir en équipe pro</button></div></div>`).join('')||'<div class="card"><p>Les espoirs ont été promus. La prochaine génération arrivera à l’intersaison.</p></div>'}</div><div class="card" style="margin-top:22px"><h2>Le suivi des carrières</h2><div class="tablewrap"><table><thead><tr><th>JOUEUR</th><th>ÂGE</th><th>NIVEAU AU POSTE</th><th>POTENTIEL AU POSTE</th><th>GAIN GÉNÉRAL</th><th>MINUTES</th><th>PHASE</th></tr></thead><tbody>${[...club().players].sort((a,b)=>a.age-b.age).map(p=>`<tr><td><button class="textbutton" onclick="inspectPlayer('${p.id}')">${p.name}</button></td><td>${p.age}</td><td>${roleNote(p)}</td><td>${potentialAtRole(p)}</td><td>${p.rating-p.dev.seasonStart>=0?'+':''}${p.rating-p.dev.seasonStart}</td><td>${Math.round(p.dev.minutes)}</td><td>${developmentBadge(p)}</td></tr>`).join('')}</tbody></table></div><p class="help">La progression compte en points de niveau général ; la note au poste résume les attributs utiles à ce rôle. Un jeune qui joue progresse davantage qu’un jeune limité aux entraînements.</p></div><div class="card" style="margin-top:22px"><h2>Les départs à la retraite</h2>${S.development.retired.filter(p=>p.club===club().name).map(p=>`<div class="news"><small>FIN SAISON ${p.season}</small>${p.name} · ${p.age} ans · ${Math.round(p.minutes)} minutes suivies dans la carrière</div>`).join('')||'<p>Aucun départ à la retraite enregistré dans votre club.</p>'}</div>`}
function nextSeason(){if(S.phase!=='ended'||economyLocked())return;const retiring=club().players.filter(p=>retirementSeason(p)<=S.season),leaving=club().players.filter(p=>p.contractEnd<=S.season&&!retiring.some(r=>r.id===p.id));if(!retiring.length&&!leaving.length){advanceSeason();return}modal=`<div class="modalback"><section class="modal contractmodal" role="dialog" aria-modal="true" aria-label="Bilan de carrière et contrats"><span class="tag">CLÔTURE DE LA SAISON</span><h2 style="margin-top:12px">Préparez les départs.</h2>${retiring.length?`<h3>${retiring.length} retraite(s) annoncée(s)</h3><ul class="expirylist">${retiring.map(p=>`<li>${p.name} · ${p.pos} · ${p.age+1} ans à l’intersaison</li>`).join('')}</ul><p class="help">Ces joueurs quittent définitivement le jeu. Le versement de leur salaire s’arrête à l’intersaison, sans indemnité dans cette simulation.</p>`:''}${leaving.length?`<h3>${leaving.length} fin(s) de contrat non prolongée(s)</h3><ul class="expirylist">${leaving.map(p=>`<li>${p.name} · ${p.pos} · ${money(p.salary)} / sem.</li>`).join('')}</ul><p class="help">Vous pouvez encore négocier leur prolongation. Sinon, ils deviendront agents libres.</p>`:''}<p class="help">Une nouvelle promotion d’espoirs arrive à chaque saison. Les postes vacants de la feuille à 23 seront complétés par les espoirs de dépannage.</p><div class="contractactions"><button onclick="modal=null;marketTab='contracts';nav('market')">Revoir les contrats</button><button class="primary" onclick="advanceSeason()">Confirmer les départs et continuer</button></div></section></div>`;render()}
